import sharp from 'sharp';
import {readFile,writeFile} from 'node:fs/promises';
import {hash} from '../engine.js';
const base=new URL('../demo/images/',import.meta.url);
const original=await readFile(new URL('astronaut.png',base));
const controls=[
 ['control-byte-copy.png',original,'Exact byte copy'],
 ['control-pixel-copy.png',await sharp(original).png({compressionLevel:0}).toBuffer(),'Lossless PNG re-encoding; same pixels'],
 ['control-resize.jpg',await sharp(original).resize(256,256).jpeg({quality:85}).toBuffer(),'Resize to 256x256 and JPEG quality 85'],
 ['control-recompress.jpg',await sharp(original).jpeg({quality:40}).toBuffer(),'JPEG recompression quality 40'],
 ['control-orientation.png',await sharp(original).rotate(270).withMetadata({orientation:6}).png().toBuffer(),'Stored rotation 270 degrees plus EXIF orientation 6; displayed upright'],
 ['control-rotation.png',await sharp(original).rotate(90).png().toBuffer(),'90-degree physical rotation without EXIF; expected orientation-invariance limitation']
];
for(const [name,bytes] of controls)await writeFile(new URL(name,base),bytes);
const manifestPath=new URL('../demo/manifest.json',import.meta.url);
const manifest=JSON.parse(await readFile(manifestPath));
const rows=controls.map(([file,bytes,transform])=>({file,kind:'generated control',parent:'astronaut.png',sha256:hash(bytes),transform,license:'Public domain source; generated by scripts/controls.js using pinned sharp'}));
if(process.argv.includes('--freeze')){manifest.files=[...manifest.files.filter(f=>f.kind==='real'),...rows];await writeFile(manifestPath,JSON.stringify(manifest,null,2)+'\n');}
else for(const row of rows){if(!manifest.files.some(f=>f.file===row.file&&f.sha256===row.sha256))throw Error('Control does not match frozen hash: '+row.file);console.log('Verified control:',row.file);}
